class BankAccount {
    // protected: directly accessible by subclasses
    protected String accountHolder;

    // private: hidden from everyone, even subclasses
    private double balance;

    public BankAccount(String holder, double initialBalance) {
        this.accountHolder = holder;
        this.balance = initialBalance;
    }

    // Public getter gives controlled read access to private balance
    public double getBalance() {
        return balance;
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
        }
    }
}

class PremiumAccount extends BankAccount {
    private double cashBackRate;

    public PremiumAccount(String holder, double initialBalance, double cashBackRate) {
        super(holder, initialBalance);
        this.cashBackRate = cashBackRate;
    }

    public void printSummary() {
        // accountHolder is protected -> directly accessible!
        System.out.println("Holder: " + accountHolder);

        // balance is private -> must call getBalance()!
        System.out.println("Balance: $" + getBalance());
        System.out.println("Cashback Rate: " + cashBackRate + "%");
    }
}

public class ExtendsDemo {
    public static void main(String[] args) {
        PremiumAccount acc = new PremiumAccount("Maria Garcia", 2500.0, 1.5);
        acc.printSummary();

        acc.deposit(500.0);
        System.out.println("After deposit balance: $" + acc.getBalance());
    }
}

