class Animal {
    void breathe() {
        System.out.println("Breathing air...");
    }
}

class DomesticPet {
    void play() {
        System.out.println("Playing with human owner...");
    }
}

// VALID: Dog extends exactly ONE direct superclass
class Dog extends Animal {
    void bark() {
        System.out.println("Woof woof!");
    }
}

// INVALID EXAMPLE (Will not compile):
// class BadDog extends Animal, DomesticPet { }
// Java forbids multiple class inheritance!

public class SingleParentDemo {
    public static void main(String[] args) {
        Dog dog = new Dog();
        dog.breathe(); // Inherited from Animal
        dog.bark();    // Defined in Dog
        System.out.println("Dog successfully extends Animal!");
    }
}

