class Customer {
    private double creditScore;

    public Customer(double score) {
        this.creditScore = score;
    }

    public double getCreditScore() {
        return creditScore;
    }

    public void setCreditScore(double score) {
        this.creditScore = score;
    }
}

class VIPCustomer extends Customer {
    public VIPCustomer(double score) {
        super(score);
    }

    public void boostCredit(double points) {
        setCreditScore(getCreditScore() + points);
    }

    public void showScore() {
        System.out.println("Score: " + getCreditScore());
    }
}

public class Main {
    public static void main(String[] args) {
        VIPCustomer vip = new VIPCustomer(720.0);
        vip.boostCredit(30.0);
        vip.showScore();
    }
}

class PaymentProcessor {
    private String apiKey;
    protected String gatewayName;

    public PaymentProcessor(String gatewayName, String apiKey) {
        this.gatewayName = gatewayName;
        this.apiKey = apiKey;
    }

    protected boolean validateApiKey(String testKey) {
        return this.apiKey.equals(testKey);
    }
}

class StripeProcessor extends PaymentProcessor {
    public StripeProcessor(String key) {
        super("Stripe", key);
    }

    public void processTransaction(String key, double amount) {
        if (validateApiKey(key)) {
            System.out.println("Processing $" + amount + " via " + gatewayName);
        } else {
            System.out.println("Authentication failed for " + gatewayName);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        StripeProcessor stripe = new StripeProcessor("sk_test_123");
        stripe.processTransaction("sk_test_123", 99.50);
        stripe.processTransaction("bad_key", 50.0);
    }
}
